  "l-1": { text: "- 간병인사용입원특약은 요양병원은 180일 한도, 가입 1년 미만 50% 보장", size: 35, weight: 700, left: 158.4, top: 147.5, track: -0.055, word: 0, family: "gm" },
  "l-2": { text: "- 암진단(최초1회한) 전이암생활비(최초 36회 보증지급, 최대 종신지급)는 가입 후 91일부터 보장", size: 35, weight: 700, left: 158.4, top: 193.5, track: -0.055, word: 0, family: "gm" },
  "l-3": { text: "- 간편한매년계속받는암진단특약S은 직전암 진단일로부터 1년이 되는 다음날부터 보장", size: 35, weight: 700, left: 158.4, top: 239.4, track: -0.055, word: 0, family: "gm" },
  "l-h1": { text: "[기존계약 해지 후, 신계약 체결 시 불이익]", size: 35, weight: 700, left: 158.4, top: 303.9, track: -0.055, word: 0, family: "gm" },
  "l-4": { text: "보험계약자가 기존 보험계약을 해지하고, 새로운 보험계약을 체결할 경우 인수거절, 보험료 인상, 보장내용 축소 등", size: 35, weight: 700, left: 158.3, top: 349.5, track: -0.055, word: 0, family: "gm" },
  "l-5": { text: "불이익이 생길 수 있습니다.", size: 35, weight: 700, left: 158.3, top: 395.4, track: -0.055, word: 0, family: "gm" },
  "l-h2": { text: "[예금자보호안내]", size: 35, weight: 700, left: 158.4, top: 457, track: -0.055, word: 0, family: "gm" },
